                RTL

;------------------------------------------------------------------------------
; vflush(mp, skipvp, flags) -> errno.  10 argument bytes.
;
; RENO CALLS IT FROM THE FILESYSTEM'S UNMOUNT and so does this: ufs_unmount
; opens with `if (error = vflush(mp, NULLVP, flags)) return (error);', which is
; the filesystem deciding whether its vnodes may be taken away.  It could have
; been called from vfs_dounmount instead, for free, both being in vfs.mod --
; and that would make flush policy the VFS's for every filesystem, which is not
; the shape upstream has.  include/modules.s says the same at VFSCORE_Vflush.
;
; ITS ABSENCE HAD A STATED REASON THAT EXPIRED.  ufs_unmount carried "vflush
; (1.11 -- no vnode has been produced from this mount until iget exists)" from
; 1.8a, and it was true until 1.8b-3a taught lookup to cross into a mount.
;------------------------------------------------------------------------------
vflush          MX      %00
                LDA     12,S
                PHA
                LDA     12,S
                PHA
                LDA     12,S
                PHA
                LDA     12,S
                PHA
                LDA     12,S
                PHA
                LDA     |_ufsImp+VFSCORE_Vflush
                                        ; MODBANK-OK: entered from C, which left
                                        ;   DBR on our bank -- and read HERE,
                                        ;   before the switch below, for exactly
                                        ;   that reason
                TAX                             ; X = target offset in the callee
                SEP     #$20
                MX      %10
                LDA     |_ufsVfsBank    ; MODBANK-OK: same, still before the
                                        ;   switch
                PHA                             ; one byte on...
                PLB                             ; ...and straight off: DBR = the
                                                ;   callee.  NET ZERO, which is
                                                ;   why it can follow the copy.
                REP     #$30
                MX      %00
                PHK                             ; ufsret_vflush is in OUR bank
                PEA     ufsret_vflush-1
                PHB                             ; target bank: DBR is the callee's
                                                ;   now, and PHB is exactly the
                                                ;   one byte RTL wants
                TXA
                DEC     A
                PHA                             ; target - 1
                RTL                             ; PILECALL
ufsret_vflush   TAY                             ; park the return value; the stack
                                                ;   fix needs the register
                TSC
                CLC
                ADC     #10
                TCS
                TYA
                PHK
                PLB                             ; DBR ours again, recovered from
                                                ;   PB rather than saved
                RTL

;------------------------------------------------------------------------------
; vattr_null(vap).  4 argument bytes.
;
; fchmod(2)'s and fchown(2)'s vattr, kern_fsetattr.c: Reno's VATTR_NULL, which
; must reach every field, so the one vfs.mod has rather than a copy.
;------------------------------------------------------------------------------
vattr_null      MX      %00
                LDA     6,S
                PHA
                LDA     6,S
                PHA
                LDA     |_ufsImp+VFSCORE_VattrNull
                                        ; MODBANK-OK: entered from C, which left
                                        ;   DBR on our bank -- and read HERE,
                                        ;   before the switch below, for exactly
                                        ;   that reason
                TAX                             ; X = target offset in the callee
                SEP     #$20
                MX      %10
                LDA     |_ufsVfsBank    ; MODBANK-OK: same, still before the
                                        ;   switch
                PHA                             ; one byte on...
                PLB                             ; ...and straight off: DBR = the
                                                ;   callee.  NET ZERO, which is
                                                ;   why it can follow the copy.
                REP     #$30
                MX      %00
                PHK                             ; ufsret_vattr_null is in OUR bank
                PEA     ufsret_vattr_null-1
                PHB                             ; target bank: DBR is the callee's
                                                ;   now, and PHB is exactly the
                                                ;   one byte RTL wants
                TXA
                DEC     A
                PHA                             ; target - 1
                RTL                             ; PILECALL
ufsret_vattr_null TAY                             ; park the return value; the stack
                                                ;   fix needs the register
                TSC
                CLC
                ADC     #4
                TCS
                TYA
                PHK
                PLB                             ; DBR ours again, recovered from
                                                ;   PB rather than saved
                RTL
